lex={}
base=set(names+words)
for w in list(base):
    for p in ['','و','ال','ب','ل']:
        if p=='ال' and (w.startswith('ال') or w not in names): continue
        x=p+w
        lex.setdefault(v(x),[]).append(x)
if __name__=='__main__':
    S="71589217218921518421924"
    def parses(s,maxtok=9):
        out=[]
        def rec(i,acc):
            if len(acc)>maxtok: return
            if i==len(s): out.append(acc[:]);return
            for j in range(i+1,min(i+4,len(s))+1):
                n=int(s[i:j])
                if n in lex: acc.append(n);rec(j,acc);acc.pop()
        rec(0,[]);return out
    P=parses(S)
    print(len(P))
    for p in P[:300]:
        print(p,' | '.join('/'.join(lex[n][:4]) for n in p))
